def reverse_words(s):
    """Return the words of s in reverse order, joined by one space."""
    return " ".join(reversed(s.split()))

def dedupe(xs):
    """Return xs with duplicates removed, keeping first-occurrence order."""
    return list(dict.fromkeys(xs))

def rotate_right(xs, k):
    """Return xs rotated right by k steps; an empty list stays empty."""
    if not xs:
        return []
    k %= len(xs)
    return xs[-k:] + xs[:-k]

def count_char(s, ch):
    """Return how many times ch occurs in s."""
    return s.count(ch)

def fib(n):
    """Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def sum_digits(n):
    """Return the sum of the decimal digits of abs(n)."""
    return sum(int(ch) for ch in str(abs(n)))

def is_prime(n):
    """Return True iff n is a prime number."""
    if n < 2:
        return False
    for d in range(2, int(n ** 0.5) + 1):
        if n % d == 0:
            return False
    return True

def gcd(a, b):
    """Return the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return abs(a)
